        if (target <= 100) {
            if (jumps.count(target)) target = jumps[target];
            positions[p] = target;
            std::cout << p << " rolled " << roll << " -> now at " << target << "\n";
            if (target == 100) {
                std::cout << p << " wins!\n";
                return;
            }
        }
        players.push(p);
    }
};

