#include <unordered_map>
#include <list>

template<typename K, typename V>
class LRUCache {
    int capacity;
    std::list<std::pair<K, V>> items;
    std::unordered_map<K, typename std::list<std::pair<K, V>>::iterator> map;
public:
    LRUCache(int cap) : capacity(cap) {}

    bool get(K key, V& outVal) {
        if (!map.count(key)) return false;
        items.splice(items.begin(), items, map[key]);
        outVal = map[key]->second;
        return true;
    }

    void put(K key, V val) {
        if (map.count(key)) {
            items.splice(items.begin(), items, map[key]);
            map[key]->second = val;
            return;
        }
        if (items.size() == capacity) {
            K lruKey = items.back().first;
            items.pop_back();
            map.erase(lruKey);
        }
        items.push_front({key, val});
        map[key] = items.begin();
    }
};

int main() {
    LRUCache<std::string, int> cache(2);
    cache.put("A", 1);
    cache.put("B", 2);
    int val;
    cache.get("A", val);
    cache.put("C", 3); // evicts B
    std::cout << "Has B: " << cache.get("B", val) << " (0 is false)\n";
    return 0;
}

